function escapeBytesText(text, quote) {
  let escaped = '';

  for (let index = 0; index < text.length; index += 1) {
    const codePoint = text.charCodeAt(index);
    const character = text[index];

    if (character === '\\') {
      escaped += '\\\\';
      continue;
    }

    if (character === quote) {
      escaped += `\\${quote}`;
      continue;
